fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 20);
        host::display::state_set(2, 3);
        host::display::state_set(3, 0);
        host::display::state_set(5, 0);
        host::display::state_set(7, 0);
        host::display::state_set(9, 0);
        host::display::state_set(10, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(8) == 0;
    host::display::state_set(8, down);
    let hp: i32 = host::display::state_get(1);
    let lives: i32 = host::display::state_get(2);
    let phase: i32 = host::display::state_get(7);
    if phase != 0 {
        if phase == 1 {
            host::display::clear(0x041808);
            host::display::draw_string(120, 190, "BOSS DOWN", 0x00ff88, 4);
        } else {
            host::display::clear(0x180408);
            host::display::draw_string(110, 190, "SHIP DESTROYED", 0xff4040, 3);
        }
        host::display::draw_string(130, 270, "TAP FOR ROUND 2", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let span: i32 = w - 120;
        let mut m: i32 = (t * 3) % (2 * span);
        if m > span { m = 2 * span - m; }
        let bossx: i32 = m;
        let mut px: i32 = host::display::pointer_x() - 20;
        if px < 0 { px = 0; }
        if px > w - 40 { px = w - 40; }
        let mut ft: i32 = host::display::state_get(9) + 1;
        let mut blx: i32 = host::display::state_get(4);
        let mut bly: i32 = host::display::state_get(3);
        if ft >= 15 && bly == 0 {
            ft = 0;
            blx = px + 18;
            bly = h - 46;
        }
        host::display::state_set(9, ft);
        if bly > 0 {
            bly = bly - 9;
            if bly <= 70 && blx >= bossx && blx < bossx + 120 {
                host::display::state_set(1, hp - 1);
                if hp - 1 <= 0 { host::display::state_set(7, 1); }
                bly = 0;
            }
            if bly < 4 { bly = 0; }
        }
        host::display::state_set(3, bly);
        host::display::state_set(4, blx);
        let mut bt: i32 = host::display::state_get(10) + 1;
        let mut bmx: i32 = host::display::state_get(6);
        let mut bmy: i32 = host::display::state_get(5);
        if bt >= 40 && bmy == 0 {
            bt = 0;
            bmx = bossx + 56;
            bmy = 74;
        }
        host::display::state_set(10, bt);
        if bmy > 0 {
            bmy = bmy + 5 + (20 - hp) / 5;
            if bmy > h - 44 && bmy < h - 20 && bmx + 8 > px && bmx < px + 40 {
                host::display::state_set(2, lives - 1);
                if lives - 1 <= 0 { host::display::state_set(7, 2); }
                bmy = 0;
            }
            if bmy > h { bmy = 0; }
        }
        host::display::state_set(5, bmy);
        host::display::state_set(6, bmx);
        host::display::clear(0x060610);
        host::display::fill_rect(bossx, 30, 120, 40, 0x8833aa);
        host::display::fill_rect(bossx + 44, 42, 32, 16, 0xffee66);
        host::display::fill_rect(bossx + 52, 46, 16, 8, 0x201030);
        host::display::fill_rect(0, 8, hp * w / 20, 6, 0xff3366);
        if bly > 0 {
            host::display::fill_rect(blx - 2, bly, 4, 12, 0x00ffcc);
        }
        if bmy > 0 {
            host::display::fill_rect(bmx, bmy, 8, 8, 0xffaa00);
        }
        host::display::fill_rect(px, h - 32, 40, 12, 0x00ddff);
        host::display::fill_triangle(px + 12, h - 32, px + 28, h - 32, px + 20, h - 44, 0x00ddff);
        let mut lf: i32 = 0;
        while lf < lives {
            host::display::fill_rect(8 + lf * 18, h - 16, 12, 8, 0x00ddff);
            lf = lf + 1;
        }
    }
    host::display::present();
}
